// POST /api/dienste/identitaet/webhook/[anbieter] – Ergebnis-Webhook des Identitätsanbieters (ÖFFENTLICH, ohne Sitzung).
//
// Schutz: HMAC-Signatur über den ROH-Body (Verfahren je Anbieter, dienste/identitaet/anbieter.js), zeitkonstanter Vergleich,
// falsche/fehlende Signatur → 401 ohne Details; Rate-Limit je IP; Body ≤ 256 KB; nur application/json; idempotent
// (Ereignis-ID). Keine Origin-Prüfung (Server-zu-Server). Frappe-Betrieb: Weiterleitung an dienste.webhook_identitaet.
import { NextResponse } from "next/server";
import { ipAdresse } from "@/lib/ipAdresse";
import { rateLimit } from "@/lib/plattform/server/rateLimit";
import { diensteBackend } from "@/lib/plattform/backend/dienste";
import { PlattformFehler } from "@/lib/plattform/fehler";

const MAX = 256 * 1024;
const antwort = (daten, status = 200) => NextResponse.json(daten, { status, headers: { "Cache-Control": "no-store" } });

export async function POST(request, ctx) {
  try {
    const { anbieter } = await ctx.params;
    rateLimit(`ident-webhook:${ipAdresse(request) || "ohne-ip"}`, 120, 60 * 1000);
    if (!/^[a-z]{2,20}$/.test(String(anbieter || ""))) return antwort({ ok: false }, 404);
    if (!String(request.headers.get("content-type") || "").toLowerCase().startsWith("application/json")) return antwort({ ok: false, error: "Erwartet wird JSON." }, 415);
    if (Number(request.headers.get("content-length") || 0) > MAX) return antwort({ ok: false }, 413);
    const roh = await request.text();
    if (roh.length > MAX) return antwort({ ok: false }, 413);
    const r = await diensteBackend().identWebhook({ anbieter, kopf: (h) => request.headers.get(h), roh });
    return antwort(r.antwort, r.status);
  } catch (e) {
    if (e instanceof PlattformFehler) return antwort({ ok: false, error: e.message }, e.status);
    console.error("[plattform-dienste] Webhook:", e?.message);
    return antwort({ ok: false }, 500);
  }
}

// POST /api/auth/login – { email, passwort } → Sitzungscookie
// Mit aktiver Zwei-Faktor-Anmeldung (und nicht gemerktem Gerät): { ok, zweiFaktor: true } + Zwischen-Cookie,
// die Sitzung entsteht erst nach POST /api/auth/zwei-faktor. Kontosperre mit Backoff → 429 (code „gesperrt“).
import { route } from "@/lib/plattform/server/route";
import { anfrageKontext, anmeldungFortsetzen } from "@/lib/plattform/server/anmeldung";
import { rateLimit, grenze } from "@/lib/plattform/server/rateLimit";
import { PlattformFehler } from "@/lib/plattform/fehler";
import { email as emailPruefen } from "@/lib/plattform/validierung";

export const POST = route({ auth: false, limit: "login" }, async ({ body, backend, request, ip }) => {
  const email = emailPruefen(body.email);
  if (!email || typeof body.passwort !== "string" || !body.passwort) throw new PlattformFehler(422, "Bitte E-Mail-Adresse und Passwort eingeben.");
  rateLimit(`loginEmail:${email}`, ...grenze("loginEmail"));
  const k = anfrageKontext(request, ip);
  const nutzer = await backend.anmelden({ email, passwort: body.passwort, ip, userAgent: k.userAgent, land: k.land });
  if (!nutzer) throw new PlattformFehler(401, "E-Mail-Adresse oder Passwort ist falsch.", "login");
  return anmeldungFortsetzen({ request, ip, nutzer, methode: "passwort" });
});
// POST /api/auth/zwei-faktor – { code, merken? } zweiter Schritt der Anmeldung (Zwischen-Cookie aus Login/E-Mail-Link)
// code: 6-stelliger TOTP-Code oder Wiederherstellungscode (XXXXX-XXXXX, einmalig). merken: Gerät 30 Tage merken.
// Falsche Codes zählen zur Kontosperre (Backoff). Erfolg: neue Sitzung, { ok, nutzer, zweiFaktorMethode, codesUebrig }.
import { route } from "@/lib/plattform/server/route";
import { zweiFaktorAbschliessen } from "@/lib/plattform/server/anmeldung";

export const POST = route({ auth: false, limit: "zweiFaktor" }, async ({ body, request, ip }) =>
  zweiFaktorAbschliessen({ request, ip, code: body.code, merken: body.merken === true })
);
// POST /api/portal/termine/oeffentlich/verwalten – Termin per Einmal-Link aus der E-Mail (Token, nur Hash gespeichert)
//   { token } → Termin · { token, aktion: "umbuchen", start } · { token, aktion: "stornieren", grund? }
import { route } from "@/lib/plattform/server/route";
import { serviceBackend } from "@/lib/plattform/backend/service";

export const POST = route({ auth: false, limit: "passwort", maxBytes: 8 * 1024 }, async ({ body }) => {
  const token = String(body.token || "").slice(0, 100);
  const s = serviceBackend();
  if (!body.aktion) return { ok: true, termin: await s.terminPerToken(token) };
  return { ok: true, termin: await s.terminPerTokenAendern(token, { aktion: body.aktion, start: body.start, grund: body.grund }) };
});

